mapper.sql:
FROM ( SELECT target_id, MIN(created_at) AS first_reported_at, COUNT(*) AS report_count, MAX(report_id) AS last_report_id FROM reports_log WHERE target_type = 'post' AND status <> 'rejected' GROUP BY target_id ) t JOIN reports_log r ON r.report_id = t.last_report_id JOIN posts p ON p.post_id = t.target_id JOIN boards b ON p.board_id = b.board_id JOIN users u ON p.user_id = u.user_id JOIN reasons rs ON r.reason_id = rs.reason_id
AND p.state = #{state} AND p.board_id = #{boardId}
AND (p.content LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\' OR u.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\')

FROM ( SELECT target_id, MIN(created_at) AS first_reported_at, COUNT(*) AS report_count, MAX(report_id) AS last_report_id FROM reports_log WHERE target_type = 'comment' AND status <> 'rejected' GROUP BY target_id ) t JOIN reports_log r ON r.report_id = t.last_report_id JOIN comments c ON c.comment_id = t.target_id JOIN posts p ON c.post_id = p.post_id JOIN boards b ON p.board_id = b.board_id JOIN users u ON c.user_id = u.user_id JOIN reasons rs ON r.reason_id = rs.reason_id
AND c.state = #{state} AND p.board_id = #{boardId}
AND (c.content LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\' OR u.name LIKE CONCAT('%', #{keyword}, '%') ESCAPE '\\')

mapper.select:
SELECT reason_id
FROM reports_log
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
ORDER BY report_id DESC
LIMIT 1

mapper.update:
UPDATE reports_log
SET status = #{status},
    resolved_at = NOW(),
    resolution_action_id = #{resolutionActionId}
WHERE target_type = #{targetType}
  AND target_id = #{targetId}
  AND status = 'pending'
